package io.rift.cronos;
import org.json.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Read-only public known-NFT check. No user wallet/funds/secret; not Android transport/runtime acceptance. */
public final class NativeHoldingsProbe {
 public static void main(String[] args)throws Exception{if(args.length!=3)throw new IllegalArgumentException("HTTPS RPC, public NFT contract, token ID required");String endpoint=args[0],contract=ReadPolicy.address(args[1]),id=ReadPolicy.token(args[2]);NetworkPolicy.endpoint(endpoint,false);try(RequestControl control=new RequestControl(60000)){
 TransferDiscovery.Rpc rpc=new TransferDiscovery.Rpc(){public void requireCronos()throws Exception{if(!"0x19".equals(call("eth_chainId",new JSONArray())))throw new IllegalStateException("Wrong chain");}public Object call(String method,JSONArray params)throws Exception{if(!Arrays.asList("eth_chainId","eth_blockNumber","eth_getBlockByNumber","eth_call").contains(method))throw new IllegalArgumentException();byte[] request=new JSONObject().put("jsonrpc","2.0").put("id",1).put("method",method).put("params",params).toString().getBytes(StandardCharsets.UTF_8);PinnedHttps.Result response=PinnedHttps.post(endpoint,"",request,control);if(response.status!=200)throw new IllegalStateException("Public provider HTTP "+response.status);JSONObject result=new JSONObject(JsonBudget.check(new String(response.body,StandardCharsets.UTF_8),262144,32));if(!"2.0".equals(result.optString("jsonrpc"))||result.optInt("id")!=1||result.has("error")||!result.has("result"))throw new IllegalStateException("Provider refused fixed read; EIP1898 support not established");return result.get("result");}};
 JSONArray rows=new JSONArray().put(new JSONObject().put("contract",contract).put("standard","ERC-721").put("tokenId",id));JSONObject first=HoldingsCheck.read(rpc,"0x000000000000000000000000000000000000dead",rows,()->control.remaining(1000));String publicOwner=first.getJSONArray("results").getJSONObject(0).getString("observedOwner");JSONObject observed=HoldingsCheck.read(rpc,publicOwner,rows,()->control.remaining(1000));System.out.println(new JSONObject().put("passed",true).put("scope","Public RPC + pure JVM helper, no Android runtime, no standard/authenticity/finality/completeness assertion").put("report",observed).toString(2));
 }}
}
